package com.dayssincedeath;

import com.google.gson.Gson;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class DaysSinceDeathPluginTest
{
    private DaysSinceDeathPlugin plugin;
    private Player local;
    private final Map<String, String> storage = new HashMap<>();
    private final AtomicReference<String> profile = new AtomicReference<>("character-a");
    private static final long START = 1_700_000_000_000L;

    @Before
    public void setUp()
    {
        plugin = new DaysSinceDeathPlugin();
        plugin.client = mock(Client.class);
        plugin.configManager = mock(ConfigManager.class);
        plugin.gson = new Gson();
        plugin.clock = Clock.fixed(Instant.ofEpochMilli(START), ZoneOffset.UTC);
        local = mock(Player.class);
        when(plugin.client.getLocalPlayer()).thenReturn(local);
        when(plugin.client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(local.getName()).thenReturn("Test character");
        when(plugin.configManager.getRSProfileKey()).thenAnswer(inv -> profile.get());
        when(plugin.configManager.getRSProfileConfiguration("dayssincedeath", "record"))
                .thenAnswer(inv -> storage.get(profile.get()));
        doAnswer(inv -> { storage.put(profile.get(), inv.getArgument(2)); return null; })
                .when(plugin.configManager).setRSProfileConfiguration(eq("dayssincedeath"), eq("record"), anyString());
    }

    @Test
    public void onlyOwnDeathCountsAndDuplicateEventsAreSuppressed()
    {
        plugin.ensureProfile();
        plugin.onActorDeath(new ActorDeath(mock(NPC.class)));
        plugin.onActorDeath(new ActorDeath(mock(Player.class)));
        assertEquals(0, plugin.visibleRecord().deaths);
        when(local.isDead()).thenReturn(true);
        plugin.onActorDeath(new ActorDeath(local));
        plugin.onActorDeath(new ActorDeath(local));
        plugin.onGameTick(new GameTick());
        plugin.onActorDeath(new ActorDeath(local));
        assertEquals(1, plugin.visibleRecord().deaths);
        when(local.isDead()).thenReturn(false);
        plugin.onGameTick(new GameTick());
        plugin.clock = Clock.fixed(Instant.ofEpochMilli(START + 60_000), ZoneOffset.UTC);
        plugin.onActorDeath(new ActorDeath(local));
        assertEquals(2, plugin.visibleRecord().deaths);
        assertEquals(60_000, plugin.visibleRecord().bestCompleted);
    }

    @Test
    public void charactersHaveSeparatePersistentRecords()
    {
        plugin.ensureProfile();
        plugin.onActorDeath(new ActorDeath(local));
        String savedA = storage.get("character-a");
        profile.set("character-b");
        plugin.ensureProfile();
        assertEquals(0, plugin.visibleRecord().deaths);
        profile.set("character-a");
        plugin.ensureProfile();
        assertEquals(1, plugin.visibleRecord().deaths);
        assertEquals(savedA, storage.get("character-a"));
    }

    @Test
    public void corruptSavedDataIsPreserved()
    {
        storage.put("character-a", "{broken");
        plugin.ensureProfile();
        plugin.onActorDeath(new ActorDeath(local));
        assertNull(plugin.visibleRecord());
        assertEquals("{broken", storage.get("character-a"));
    }

    @Test
    public void missingCharacterAndLoggedOutEventsNeverWrite()
    {
        profile.set(null);
        plugin.onActorDeath(new ActorDeath(local));
        assertTrue(storage.isEmpty());
        profile.set("character-a");
        when(plugin.client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
        plugin.onActorDeath(new ActorDeath(local));
        assertTrue(storage.isEmpty());
    }
}

package com.dayssincedeath;

import org.junit.Test;
import static org.junit.Assert.*;

public class DeathRecordTest
{
    private static final long START = 1_700_000_000_000L;
    private static final long HOUR = 3_600_000;

    @Test
    public void firstUseDoesNotInventADeathOrPersonalBest()
    {
        DeathRecord record = DeathRecord.start(START);
        assertTrue(record.valid());
        assertEquals(0, record.lastDeath);
        assertEquals(0, record.deaths);
        assertEquals(2 * HOUR, record.elapsed(START + 2 * HOUR));
        assertEquals(0, record.best(START + 2 * HOUR));
    }

    @Test
    public void firstDeathStartsAStreakWithoutCountingPartialHistoryAsBest()
    {
        DeathRecord record = DeathRecord.start(START).died(START + 10 * HOUR);
        assertEquals(0, record.bestCompleted);
        assertEquals(1, record.deaths);
        assertEquals(HOUR, record.best(START + 11 * HOUR));
    }

    @Test
    public void laterDeathResetsCurrentAndKeepsLongestFullInterval()
    {
        DeathRecord record = DeathRecord.start(START).died(START + HOUR)
                .died(START + 5 * HOUR).died(START + 6 * HOUR);
        assertEquals(3, record.deaths);
        assertEquals(4 * HOUR, record.bestCompleted);
        assertEquals(0, record.elapsed(START + 6 * HOUR));
        assertEquals(4 * HOUR, record.best(START + 6 * HOUR));
        assertEquals(5 * HOUR, record.best(START + 11 * HOUR));
    }

    @Test
    public void backwardsClockNeverCreatesNegativeDuration()
    {
        DeathRecord record = DeathRecord.start(START).died(START + HOUR);
        assertEquals(0, record.elapsed(START));
        DeathRecord after = record.died(START);
        assertTrue(after.valid());
        assertEquals(START + HOUR, after.lastDeath);
        assertEquals(0, after.bestCompleted);
    }

    @Test
    public void inconsistentSavedRecordsAreRejected()
    {
        assertFalse(new DeathRecord(0, 0, 0, 0).valid());
        assertFalse(new DeathRecord(START, START - 1, 0, 1).valid());
        assertFalse(new DeathRecord(START, 0, 0, 1).valid());
        assertFalse(new DeathRecord(START, START, -1, 1).valid());
    }
}

package com.dayssincedeath;

import org.junit.Test;
import static org.junit.Assert.*;

public class DisplayUnitTest
{
    private static final long HOUR = 3_600_000;
    private static final long DAY = 24 * HOUR;

    @Test
    public void automaticFormatCrossesEachBoundary()
    {
        assertEquals("0m 0s", DisplayUnit.AUTOMATIC.format(-1));
        assertEquals("1m 1s", DisplayUnit.AUTOMATIC.format(61_000));
        assertEquals("1h 0m", DisplayUnit.AUTOMATIC.format(HOUR));
        assertEquals("1d 2h 0m", DisplayUnit.AUTOMATIC.format(DAY + 2 * HOUR));
        assertEquals("1w 1d 2h", DisplayUnit.AUTOMATIC.format(8 * DAY + 2 * HOUR));
        assertEquals("1y 1w 1d", DisplayUnit.AUTOMATIC.format(373 * DAY));
    }

    @Test
    public void selectedUnitsDisplayTotals()
    {
        assertEquals("36.00 hours", DisplayUnit.HOURS.format(DAY + 12 * HOUR));
        assertEquals("1.50 days", DisplayUnit.DAYS.format(DAY + 12 * HOUR));
        assertEquals("2.00 weeks", DisplayUnit.WEEKS.format(14 * DAY));
        assertEquals("2.00 years", DisplayUnit.YEARS.format(730 * DAY));
    }
}
